import os, re, json, shutil, subprocess, sys

BASE = "/tmp/probe/frontmatter/wk2/runs"
BIN = "/tmp/orig/marmite_ref"

def build(name, files, args=(), config=None, verbose=0, keep=True):
    d = os.path.join(BASE, name)
    if os.path.exists(d):
        shutil.rmtree(d)
    ind = os.path.join(d, "in")
    outd = os.path.join(d, "out")
    os.makedirs(ind)
    for fn, content in files.items():
        p = os.path.join(ind, fn)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        if isinstance(content, bytes):
            open(p, "wb").write(content)
        else:
            open(p, "w").write(content)
    if config is not None:
        open(os.path.join(ind, "marmite.yaml"), "w").write(config)
    cmd = [BIN]
    if verbose:
        cmd.append("-" + "v" * verbose)
    cmd += list(args)
    cmd += [ind, outd]
    r = subprocess.run(cmd, capture_output=True, text=True)
    return {"dir": d, "in": ind, "out": outd, "rc": r.returncode,
            "stdout": r.stdout, "stderr": r.stderr, "cmd": cmd}

def rd(res, rel):
    p = os.path.join(res["out"], rel)
    if not os.path.exists(p):
        return None
    return open(p, encoding="utf-8", errors="replace").read()

def ls(res):
    out = []
    for root, dirs, fs in os.walk(res["out"]):
        if "static" in dirs:
            dirs.remove("static")
        for f in fs:
            out.append(os.path.relpath(os.path.join(root, f), res["out"]))
    return sorted(out)

def urls(res):
    t = rd(res, "urls.json")
    return json.loads(t) if t else None

def mj(res):
    t = rd(res, "marmite.json")
    return json.loads(t) if t else None

def art(res, name, extra=None):
    dst = os.path.join("/tmp/probe/artifacts/frontmatter", name)
    if os.path.exists(dst):
        shutil.rmtree(dst)
    os.makedirs(dst)
    shutil.copytree(res["in"], os.path.join(dst, "in"))
    for f in ls(res):
        s = os.path.join(res["out"], f)
        t = os.path.join(dst, "out", f)
        os.makedirs(os.path.dirname(t), exist_ok=True)
        shutil.copy(s, t)
    open(os.path.join(dst, "cmd.txt"), "w").write(" ".join(res["cmd"]) + "\n")
    open(os.path.join(dst, "stderr.txt"), "w").write(res["stderr"])
    if extra:
        open(os.path.join(dst, "notes.txt"), "w").write(extra)

def article(res, slug):
    t = rd(res, slug + ".html")
    if t is None:
        return None
    m = re.search(r'<article class="h-entry">.*?</article>', t, re.S)
    return m.group(0) if m else t
